"""SkillGenBench-equivalent required loading, retaining the original generated bytes."""
from dataclasses import replace
import os
from pathlib import Path

from degradation_lab.io import read, sha256
from downstream_eval.sgb import runner
from . import fla, scrapy024
from .common import LAB, native_trial

ADAPTERS = {'scrapy-task-024': scrapy024, 'fla_packet_cadence_scope_validator_002': fla}
NOTE = Path(__file__).with_name('read_required.md')


def verify_assets():
    return {task: adapter.verify_assets() for task, adapter in ADAPTERS.items()}


def execution_config(output, generator_run_id, conditions):
    output = Path(output)
    task_id = read(output / 'task_config.json')['task_id']
    original = ADAPTERS[task_id].execution_config(output, generator_run_id, conditions)
    return replace(original, trial_prefix='read-' + output.name + '-')


def configure(output, label, mode, config):
    from harbor.models.trial.config import TrialConfig
    raw = runner.trial_config(output, label, mode, config)
    raw['extra_instruction_paths'] = [str(config.task_path / 'runtime-note.md'), str(NOTE)]
    return TrialConfig.model_validate(raw)


def grade_export(trial, output):
    task_id = Path(trial.config.task.path).name
    path, digest = trial._scrapy041_export
    if sha256(path) != digest:
        raise ValueError('Native export changed')
    return ADAPTERS[task_id].score(path, Path(output) / 'score', expected_sha256=digest)


def paid_batch(output):
    if os.environ.get('SGB_AUDIT_ALLOW_PAID') != '1':
        raise RuntimeError('Required-read pilot not enabled')
    verify_assets()
    output = Path(output)
    if read(output / 'readiness.json')['status'] != 'PASS':
        raise RuntimeError('Zero-model preparation has not passed')
    profile = read(output / 'profile.json')
    config = execution_config(output, profile['generator_run_id'], profile['conditions'])
    from downstream_eval.sgb.scrapy024 import body_exposure
    return runner.execute_batch(LAB, output, config, run_trial=native_trial, grade=grade_export,
        exposure=body_exposure, task_success=lambda result: result['task_success'], configure_trial=configure)
